1	// Acceptance tests for the change request:
2	//   "Invoices should move through stages. First a draft. Then I send it. Then it gets paid. Keep a
3	//    record when I send one. Only let me take payment once it has been sent."
4	//
5	// An invoice now moves through three stages: DRAFT -> SENT -> PAID. A freshly created invoice is a
6	// DRAFT. A draft offers a control to SEND it (invoice-send-<id>); sending flips THAT invoice's
7	// status to SENT and appends one audit record — INVOICE_SENT id=<id> amount=<amount> — so the send
8	// can be checked back later (the UI only shows the status). Payment is GATED on sending: the mark-
9	// paid control (invoice-pay-<id>) is only offered once the invoice has been sent — a draft cannot
10	// be paid. Once sent, paying it works as before (status -> PAID, INVOICE_PAID record).
11	//
12	// Asserts ONLY through the two public channels: the UI (data-testid) and the audit file
13	// (auditLines()). Data is arranged via resetAndSeed; the send/pay flows are driven through the UI.
14	// Seed honours invoices: { id, projectId, amount, status } — status is seeded to place an invoice at
15	// a chosen stage ('DRAFT' / 'SENT' / 'PAID').
16	//
17	// Status labels are asserted case-insensitively (/^draft$/i, /^sent$/i, /^paid$/i) so the test
18	// tolerates whichever casing the feature renders. The audit amount is matched with an optional
19	// trailing ".00" so a plain or two-decimal rendering both pass. Amounts are distinct whole numbers so
20	// no value is a substring of another. This test SHOULD FAIL before the change: today a draft has no
21	// send control and can be paid directly.
22	import { test, expect } from '@playwright/test';
23	import { resetAndSeed } from '../support/seed';
24	import { auditLines } from '../support/audit';
25	
26	test.describe('invoice stages: draft -> sent -> paid', () => {
27	  test('a newly created invoice is a draft: it can be sent but not yet paid', async ({ page }) => {
28	    await resetAndSeed({
29	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
30	      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
31	      invoices: [],
32	    });
33	
34	    await page.goto('/projects');
35	    await page.getByTestId('project-open-1').click();
36	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
37	
38	    // Create a new invoice through the form. RESTART IDENTITY + empty invoices => it gets id 1.
39	    await page.getByTestId('invoice-form-amount').fill('250');
40	    await page.getByTestId('invoice-form-submit').click();
41	
42	    const row = page.getByTestId('invoice-row-1');
43	    await expect(row).toBeVisible();
44	
45	    // First a draft: the new invoice starts in the DRAFT stage.
46	    await expect(row.getByTestId('invoice-status')).toHaveText(/^draft$/i);
47	
48	    // A draft can be sent, but cannot yet be paid — payment is only offered once it has been sent.
49	    await expect(page.getByTestId('invoice-send-1')).toBeVisible();
50	    await expect(page.getByTestId('invoice-pay-1')).toHaveCount(0);
51	  });
52	
53	  test('sending a draft moves it to sent, keeps a record, and only then allows payment', async ({ page }) => {
54	    await resetAndSeed({
55	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
56	      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
57	      invoices: [{ id: 1, projectId: 1, amount: 120, status: 'DRAFT' }],
58	    });
59	
60	    await page.goto('/projects');
61	    await page.getByTestId('project-open-1').click();
62	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
63	
64	    const row = page.getByTestId('invoice-row-1');
65	    await expect(row).toBeVisible();
66	
67	    // Starts as a draft: a send control is offered, and it cannot be paid yet.
68	    await expect(row.getByTestId('invoice-status')).toHaveText(/^draft$/i);
69	    await expect(page.getByTestId('invoice-send-1')).toBeVisible();
70	    await expect(page.getByTestId('invoice-pay-1')).toHaveCount(0);
71	
72	    // reset cleared the audit file — nothing has been sent yet.
73	    expect(auditLines()).toEqual([]);
74	
75	    await page.getByTestId('invoice-send-1').click();
76	
77	    // Now sent: the status reflects the SENT stage.
78	    await expect(row.getByTestId('invoice-status')).toHaveText(/^sent$/i);
79	
80	    // Exactly one record was kept for the send, naming the invoice and its amount — and only that one.
81	    await expect
82	      .poll(() => auditLines().filter((l) => /^INVOICE_SENT id=1 amount=120(\.0+)?$/.test(l)))
83	      .toHaveLength(1);
84	    expect(auditLines()).toHaveLength(1);
85	
86	    // Only now that it has been sent is payment offered; there is nothing left to send.
87	    await expect(page.getByTestId('invoice-pay-1')).toBeVisible();
88	    await expect(page.getByTestId('invoice-send-1')).toHaveCount(0);
89	
90	    // And paying it still works: status -> PAID, with its own INVOICE_PAID record alongside the send.
91	    await page.getByTestId('invoice-pay-1').click();
92	    await expect(row.getByTestId('invoice-status')).toHaveText(/^paid$/i);
93	
94	    await expect.poll(() => auditLines()).toHaveLength(2);
95	    const lines = auditLines();
96	    expect(lines.some((l) => /^INVOICE_SENT id=1 amount=120(\.0+)?$/.test(l))).toBe(true);
97	    expect(lines.some((l) => /^INVOICE_PAID id=1 amount=120(\.0+)?$/.test(l))).toBe(true);
98	  });
99	
100	  test('a draft cannot be paid but an already-sent invoice can', async ({ page }) => {
101	    // Two invoices side by side: one still a DRAFT, one already SENT.
102	    await resetAndSeed({
103	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
104	      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
105	      invoices: [
106	        { id: 1, projectId: 1, amount: 120, status: 'DRAFT' },
107	        { id: 2, projectId: 1, amount: 340, status: 'SENT' },
108	      ],
109	    });
110	
111	    await page.goto('/projects');
112	    await page.getByTestId('project-open-1').click();
113	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
114	
115	    const draft = page.getByTestId('invoice-row-1');
116	    const sent = page.getByTestId('invoice-row-2');
117	
118	    // The draft: sendable, not payable.
119	    await expect(draft.getByTestId('invoice-status')).toHaveText(/^draft$/i);
120	    await expect(page.getByTestId('invoice-send-1')).toBeVisible();
121	    await expect(page.getByTestId('invoice-pay-1')).toHaveCount(0);
122	
123	    // The already-sent invoice: payable, with nothing left to send.
124	    await expect(sent.getByTestId('invoice-status')).toHaveText(/^sent$/i);
125	    await expect(page.getByTestId('invoice-pay-2')).toBeVisible();
126	    await expect(page.getByTestId('invoice-send-2')).toHaveCount(0);
127	
128	    // Seeded straight into their stages — no send happened, so the audit file is empty.
129	    expect(auditLines()).toEqual([]);
130	  });
131	
132	  test('sending one draft records its own line and leaves its siblings untouched', async ({ page }) => {
133	    await resetAndSeed({
134	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
135	      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
136	      invoices: [
137	        { id: 1, projectId: 1, amount: 120, status: 'DRAFT' },
138	        { id: 2, projectId: 1, amount: 340, status: 'DRAFT' },
139	      ],
140	    });
141	
142	    await page.goto('/projects');
143	    await page.getByTestId('project-open-1').click();
144	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
145	
146	    const first = page.getByTestId('invoice-row-1');
147	    const second = page.getByTestId('invoice-row-2');
148	
149	    // Send the first draft. It moves to SENT; the second is still a draft (untouched).
150	    await page.getByTestId('invoice-send-1').click();
151	    await expect(first.getByTestId('invoice-status')).toHaveText(/^sent$/i);
152	    await expect(second.getByTestId('invoice-status')).toHaveText(/^draft$/i);
153	    await expect(page.getByTestId('invoice-send-2')).toBeVisible();
154	    await expect(page.getByTestId('invoice-pay-2')).toHaveCount(0);
155	
156	    // One record so far, for invoice 1 and its amount — and only that one.
157	    await expect
158	      .poll(() => auditLines().filter((l) => /^INVOICE_SENT id=1 amount=120(\.0+)?$/.test(l)))
159	      .toHaveLength(1);
160	    expect(auditLines()).toHaveLength(1);
161	
162	    // Now send the second draft too — a separate record is kept for it as well.
163	    await page.getByTestId('invoice-send-2').click();
164	    await expect(second.getByTestId('invoice-status')).toHaveText(/^sent$/i);
165	
166	    await expect.poll(() => auditLines()).toHaveLength(2);
167	    const lines = auditLines();
168	    expect(lines.some((l) => /^INVOICE_SENT id=1 amount=120(\.0+)?$/.test(l))).toBe(true);
169	    expect(lines.some((l) => /^INVOICE_SENT id=2 amount=340(\.0+)?$/.test(l))).toBe(true);
170	  });
171	});
