27	        { id: 2, clientId: 1, name: 'Warehouse automation' },
28	      ],
29	      invoices: [
30	        { id: 1, projectId: 1, amount: 120 },
31	        { id: 2, projectId: 1, amount: 300 },
32	        // Belongs to a DIFFERENT project — it must not appear or count toward project 1's total.
33	        { id: 3, projectId: 2, amount: 999 },
34	      ],
35	    });
