49	    await expect(second).toBeVisible();
50	    await expect(second.getByTestId('invoice-amount')).toContainText('$300.00');
51	
52	    // The other project's invoice is not shown here.
53	    await expect(page.getByTestId('invoice-row-3')).toHaveCount(0);
54	
55	    // What they add up to: 120 + 300 = 420 (and NOT including the other project's 999).
56	    await expect(page.getByTestId('project-invoices-total')).toContainText('$420.00');
57	    await expect(page.getByTestId('project-invoices-total')).not.toContainText('999');
58	  });
59	
60	  test('adds a new invoice for an amount, which then appears and is added into the total', async ({ page }) => {
61	    await resetAndSeed({
62	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
63	      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
64	      invoices: [],
65	    });
66	
67	    await page.goto('/projects');
68	    await page.getByTestId('project-open-1').click();
69	
70	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
71	    await expect(page.getByTestId('invoice-form')).toBeVisible();
72	    // No invoices seeded, so no invoice rows yet.
73	    await expect(page.getByTestId('invoice-amount')).toHaveCount(0);
74	
75	    await page.getByTestId('invoice-form-amount').fill('250');
76	    await page.getByTestId('invoice-form-submit').click();
77	
78	    // Reset RESTART IDENTITY + empty invoices seed => the first created invoice has id 1.
79	    const row = page.getByTestId('invoice-row-1');
80	    await expect(row).toBeVisible();
81	    await expect(row.getByTestId('invoice-amount')).toContainText('$250.00');
82	
83	    // The newly added amount is what the invoices add up to.
84	    await expect(page.getByTestId('project-invoices-total')).toContainText('$250.00');
